import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"故障排查","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/troubleshooting.md","filePath":"zh-CN/guide/troubleshooting.md","lastUpdated":1793173149000}`),a={name:`zh-CN/guide/troubleshooting.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to “故障排查”">​</a></h1><p>本页汇总了常见问题及其解决办法。</p><h2 id="应用无法启动或启动即崩溃" tabindex="-1">应用无法启动或启动即崩溃 <a class="header-anchor" href="#应用无法启动或启动即崩溃" aria-label="Permalink to “应用无法启动或启动即崩溃”">​</a></h2><p>现象：Sudoku 打不开、刚启动就崩溃，或显示意外错误。</p><p>可尝试的步骤：</p><ol><li>确认设备满足最低要求（iOS/iPadOS 16+、macOS 15+）。</li><li>强制退出应用后重新启动。</li><li>重启设备。</li><li>从 App Store 重新安装应用。</li><li>如果问题依旧，请在项目仓库中提交 issue 并附上详细信息。</li></ol><h2 id="性能问题" tabindex="-1">性能问题 <a class="header-anchor" href="#性能问题" aria-label="Permalink to “性能问题”">​</a></h2><p>如果游戏卡顿或运行缓慢：</p><ol><li>关闭其他占用资源较多的应用。</li><li>在 Mac 上，打开“活动监视器”检查是否有高 CPU 占用。</li><li>在较旧的设备上，可以试试更简单的难度（简单或中等）。</li></ol><h2 id="icloud-同步不工作" tabindex="-1">iCloud 同步不工作 <a class="header-anchor" href="#icloud-同步不工作" aria-label="Permalink to “iCloud 同步不工作”">​</a></h2><p>如果进度没有在设备间同步：</p><ol><li>确认所有设备登录的是同一个 Apple ID。</li><li>检查 macOS 的“系统设置”或 iOS/iPadOS 的“设置”中是否已启用 iCloud 云盘。</li><li>确认网络连接正常。</li><li>在“设置 → [你的名字] → iCloud → 使用 iCloud 的 App”中，将 Sudoku 的 iCloud 开关关闭后再重新打开。</li><li>重启所有设备后重试。</li></ol><h2 id="game-center-无法连接" tabindex="-1">Game Center 无法连接 <a class="header-anchor" href="#game-center-无法连接" aria-label="Permalink to “Game Center 无法连接”">​</a></h2><p>如果 Game Center 的成就或排行榜没有更新：</p><ol><li>确认已登录 Game Center（iOS 上为“设置 → Game Center”；Mac 上为“系统设置”）。</li><li>检查网络连接。</li><li>退出 Game Center 登录后重新登录。</li></ol><h2 id="查看日志" tabindex="-1">查看日志 <a class="header-anchor" href="#查看日志" aria-label="Permalink to “查看日志”">​</a></h2><p>排查崩溃时，应用日志会很有帮助。在 Mac 上使用沙盒（App Store 版）构建时，请查看：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>~/Library/Containers/com.w3cub.sudoku/Data/Library/Logs/sudoku/sudoku.log</span></span></code></pre></div><p>在 iOS/iPadOS 上，将设备连接到 Mac，使用 Console.app 查看日志，并按“Sudoku”筛选。</p><h2 id="重置应用" tabindex="-1">重置应用 <a class="header-anchor" href="#重置应用" aria-label="Permalink to “重置应用”">​</a></h2><p>如需重置设置并清除本地数据（Mac）：</p><ol><li>退出 Sudoku</li><li>删除容器（请谨慎——这会删除所有设置、统计数据和游戏存档）：</li></ol><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.sudoku</span></span></code></pre></div><ol start="3"><li>重新打开 Sudoku 并重新配置。</li></ol><p>在 iPhone/iPad 上，删除并重新安装应用即可重置所有数据。</p><p><strong>注意</strong>：如果你使用了 iCloud 同步，在某一台设备上重置后，应用重新启动时可能会再次从 iCloud 下载数据。若要在所有设备上彻底重置，可能需要在每台设备上分别执行重置。</p><h2 id="报告问题" tabindex="-1">报告问题 <a class="header-anchor" href="#报告问题" aria-label="Permalink to “报告问题”">​</a></h2><p>提交 issue 时，请附上：</p><ul><li>设备类型（iPhone、iPad 或 Mac）</li><li>系统版本（设置 → 通用 → 关于本机）</li><li>Sudoku 版本（设置 → 关于）</li><li>复现步骤</li><li>如有，附上日志或截图</li></ul><p>这能帮助维护者更快地定位并修复问题。</p>`,30)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};